def transform(grid):
    if not grid: return []
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0

    sep_rows = []
    for r in range(n):
        val = grid[r][0]
        if all(grid[r][c] == val for c in range(m)):
            sep_rows.append(r)

    sep_cols = []
    for c in range(m):
        val = grid[0][c]
        if all(grid[r][c] == val for r in range(n)):
            sep_cols.append(c)

    if not sep_rows and not sep_cols:
        return []

    sep_color = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]

    from collections import Counter
    counts = Counter()
    for r in range(n):
        for c in range(m):
            if r in sep_rows: continue
            if c in sep_cols: continue
            counts[grid[r][c]] += 1

    maj_color = max(counts, key=counts.get) if counts else sep_color

    h_sections = []
    prev = 0
    for s in sep_rows:
        h_sections.append((prev, s))
        prev = s + 1
    h_sections.append((prev, n))

    v_sections = []
    prev = 0
    for s in sep_cols:
        v_sections.append((prev, s))
        prev = s + 1
    v_sections.append((prev, m))

    res = []
    for s_r, e_r in h_sections:
        row_res = []
        for s_c, e_c in v_sections:
            imp = 0
            for r in range(s_r, e_r):
                for c in range(s_c, e_c):
                    val = grid[r][c]
                    if val != sep_color and val != maj_color:
                        imp += 1
            if imp >= 2:
                row_res.append(1)
            else:
                row_res.append(maj_color)
        res.append(row_res)

    return res
